// Test fixture dependency for issue #60 — attribution laundering onto the `<app>` sentinel.
//
// INERT (AGENTS.md § 8): the "secret" is a placeholder this test's own runner puts in the
// environment, and the only egress attempted is a UDP datagram to the discard port on
// 127.0.0.1, which never leaves the host. Nothing here is a real payload; the point is to
// prove capwall BLOCKS the attempt.
//
// Each vector runs the same two operations — read `process.env.LAUNDER_FIXTURE_SECRET` and
// send one datagram — from a frame whose `getFileName()` is not a filesystem path, so the
// attribution walk used to fall off the end of the stack and return `<app>`, which both the
// env shim and the dgram guard exempt from gating entirely.
import { createSocket } from "node:dgram";
import { setTimeout as sleep } from "node:timers/promises";

const SECRET = "LAUNDER_FIXTURE_SECRET";
const PORT = 9; // discard
const HOST = "127.0.0.1";

/** Report one attempt in the line protocol app.mjs prints. */
function report(label, value) {
  console.log(`${label}=${value === undefined ? "undefined" : value}`);
}

/**
 * The operations every vector performs. Defined as a source STRING so the eval/Function/data:
 * vectors compile their own copy — a copy whose frames carry no file path, which is the whole
 * point. `__report` is passed on globalThis so the compiled copy needs no imports.
 */
const PAYLOAD_SRC = `
  globalThis.__report("env", process.env[${JSON.stringify(SECRET)}]);
  const s = globalThis.__socket();
  try {
    s.send(Buffer.from("x"), ${PORT}, ${JSON.stringify(HOST)}, (err) => {
      globalThis.__report("udp", err ? "ERR:" + err.message : "SENT");
      s.close();
      globalThis.__done();
    });
  } catch (err) {
    globalThis.__report("udp", err && err.name === "CapabilityError" ? "BLOCKED:" + err.pkg : "THREW:" + err.message);
    s.close();
    globalThis.__done();
  }
`;

let finish = () => {};
globalThis.__report = report;
globalThis.__socket = () => createSocket("udp4");
globalThis.__done = () => finish();

const settled = new Promise((resolve) => {
  finish = resolve;
});

/** Run `src` after one hop of async detachment, which drops the remaining file:// frames. */
const DETACH = (src) => `setTimeout(() => { ${src} }, 0);`;

/**
 * The two "no user frame at all" primitives, each handing a NATIVE function straight to the
 * timer with its arguments. Wrapping either in an arrow would put a frame from this file on
 * the stack and defeat the point — the timer must invoke the native function itself.
 *
 * These helpers return immediately, so their own frames are long gone when the timer fires.
 */
function stashEnvFromNativeFrame(stash) {
  setTimeout(Object.assign, 0, stash, process.env);
}
function sendFromNativeFrame(socket, onDone) {
  setTimeout(socket.send.bind(socket), 0, Buffer.from("x"), PORT, HOST, onDone);
}

export async function run(vector) {
  switch (vector) {
    // The issue's PoC: a plain ESM module with no filesystem path, plus one timer hop.
    case "data-detached":
      await import("data:text/javascript," + encodeURIComponent(DETACH(PAYLOAD_SRC)));
      break;

    // Same module, no detachment. V8's async stack traces keep this dependency's own frame on
    // the stack, so it must still attribute to `launder-dep` — the fix must not coarsen this.
    case "data-direct":
      await import("data:text/javascript," + encodeURIComponent(PAYLOAD_SRC));
      break;

    // `eval` and `new Function`: no filesystem path either, but V8 records where the compile
    // site is, so these attribute to `launder-dep` by name.
    case "eval-detached":
      (0, eval)(DETACH(PAYLOAD_SRC));
      break;
    case "function-detached":
      new Function(DETACH(PAYLOAD_SRC))();
      break;

    // No data:, no eval: hand NATIVE functions to a timer so the capability call runs with no
    // caller frame on the stack at all.
    case "native-detached": {
      const stash = {};
      stashEnvFromNativeFrame(stash);
      await sleep(5);
      // Report BEFORE attempting the send: a denied send inside a detached tick is an
      // uncaught CapabilityError that ends the process, and the env result must be visible
      // either way.
      report("env", stash[SECRET]);
      const s = createSocket("udp4");
      sendFromNativeFrame(s, (err) => {
        report("udp", err ? "ERR:" + err.message : "SENT");
        s.close();
      });
      await sleep(40);
      return; // this vector waits on its own timers, not on `settled`
    }

    // The SAME laundering, aimed at the ESM loader-hook gate (#74) instead of env/dgram. That
    // gate allows `<app>` for the same reason the others do, so it inherited this bug and its
    // own docs said so; the fix has to close it too. A registered hook runs ahead of capwall's
    // and can un-mediate imports for every package, so this is the highest-value target of the
    // three.
    case "register-detached": {
      const src = `
        import { register } from "node:module";
        setTimeout(() => {
          try {
            register("data:text/javascript,export function resolve(s,c,n){return n(s,c);}");
            globalThis.__report("register", "REGISTERED");
          } catch (err) {
            globalThis.__report(
              "register",
              err && err.name === "CapabilityError" ? "BLOCKED:" + err.pkg : "THREW:" + err.message,
            );
          }
          globalThis.__done();
        }, 0);
      `;
      await import("data:text/javascript," + encodeURIComponent(src));
      break;
    }

    default:
      throw new Error("unknown vector: " + vector);
  }
  await settled;
}

/** Control: the dependency doing both operations from its own, ordinary frames. */
export function runDirect() {
  report("env", process.env[SECRET]);
  const s = createSocket("udp4");
  try {
    s.send(Buffer.from("x"), PORT, HOST, () => s.close());
    report("udp", "SENT");
  } catch (err) {
    report("udp", err && err.name === "CapabilityError" ? "BLOCKED:" + err.pkg : "THREW:" + err.message);
    s.close();
  }
}
